// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // owner starts as address(0); transfer ownership from address(0) to actor
        vm.prank(address(0));
        c.transferOwnership(actor);
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok, "owner must be able to call owned()");
    }
}
